function Morphinator_AddMorphs(list)
    if type(list) ~= "table" then return end
    for _, entry in ipairs(list) do
        if entry.id and entry.name then
            table.insert(MorphinatorData, { id = entry.id, name = entry.name })
        end
    end
end
